def main():
    out = Path(__file__).resolve().parents[1] / "data" / "eval" / "qa_batch1.jsonl"
    out.parent.mkdir(parents=True, exist_ok=True)
    with open(out, "w", encoding="utf-8") as f:
        for i, (cat, q, a, foods, culture, risk, trig, srcs) in enumerate(ITEMS, 1):
            f.write(json.dumps({
                "id": f"qa1-{i:03d}", "question": q, "reference_answer": a, "category": cat,
                "food_tags": foods, "culture_tag": culture, "risk_level": risk, "expected_triage": trig,
                "source_ids": srcs, "synthetic": True, "origin": "OnTrack team synthetic batch 1 (AI-assisted draft)",
                "review_status": "draft",
            }, ensure_ascii=False) + "\n")
    from collections import Counter
    print(out, len(ITEMS), Counter(x[0] for x in ITEMS), Counter(x[4] for x in ITEMS), Counter(x[6] for x in ITEMS))


if __name__ == "__main__":
    main()
